#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    const char *NO_INPUT            = "NO_INPUT";
    const char *BAD_INPUT           = "BAD_INPUT";
    const char *OUT_OF_RANGE        = "OUT_OF_RANGE";
    const char *OVERFLOW_GUARD      = "OVERFLOW_GUARD";
    const char *STEP_LIMIT_EXCEEDED = "STEP_LIMIT_EXCEEDED";

    if (argc < 2) {
        puts(NO_INPUT);
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        puts(BAD_INPUT);
        return 0;
    }
    if (n < 1) {
        puts(BAD_INPUT);
        return 0;
    }
    if ((unsigned long)n > 1000000000UL) {
        puts(OUT_OF_RANGE);
        return 0;
    }

    unsigned long long cur = (unsigned long long)n;
    long steps = 0;

    while (1) {
        if (cur == 1ULL) {
            printf("n=%ld steps=%ld\n", n, steps);
            break;
        }
        if (steps > 999999) {
            puts(STEP_LIMIT_EXCEEDED);
            break;
        }
        if (cur > 1000000000000000ULL) {
            puts(OVERFLOW_GUARD);
            break;
        }
        if ((cur & 1ULL) == 0ULL) {
            cur >>= 1;
        } else {
            cur = cur * 3ULL + 1ULL;
        }
        ++steps;
    }
    return 0;
}
